import React, { useState } from "react";
import api from "../services/api";
import "./AutomationWidget.css"; 

const AutomationWidget = () => {
  const [statusMessage, setStatusMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const handleAutomation = async (serviceName) => {
    setLoading(true);
    setStatusMessage(`Restarting ${serviceName}...`);

    try {
      const token = localStorage.getItem("token");
      const response = await api.post("/api/automation/resolve/", 
        { service: serviceName }, 
        { headers: { Authorization: `Token ${token}` } }
      );

      setStatusMessage(response.data.message || "Automation completed.");
    } catch (error) {
      setStatusMessage("Failed to automate resolution.");
    }

    setLoading(false);
  };

  return (
    <div className="widget automation-widget">
      <h3>Automated Resolution</h3>
      <button onClick={() => handleAutomation("apache2")} disabled={loading}>Restart Apache</button>
      <button onClick={() => handleAutomation("nginx")} disabled={loading}>Restart Nginx</button>
      <button onClick={() => handleAutomation("mysql")} disabled={loading}>Restart MySQL</button>
      <button onClick={() => handleAutomation("postgresql")} disabled={loading}>Restart PostgreSQL</button>
      {statusMessage && <p>{statusMessage}</p>}
    </div>
  );
};

export default AutomationWidget;
